	    Invoice entity = addToPayments(event.getInvoiceId(), event.getAddTo() );
        
    	// ------------------------------------------
    	// emit to subscribers that find one
    	// ------------------------------------------    	
        emitFindInvoice( entity );

    	// ------------------------------------------
