/*
 * @param	event RemovePaymentsFromInvoiceEvent
 */
@EventHandler( payloadType=RemovePaymentsFromInvoiceEvent.class)
public void handle( RemovePaymentsFromInvoiceEvent event) {
    LOGGER.info("handling RemovePaymentsFromInvoiceEvent - " + event );

    Invoice entity = removeFromPayments(event.getInvoiceId(), event.getRemoveFrom() );
    
	// ------------------------------------------
	// emit to subscribers that find one
	// ------------------------------------------    	
    emitFindInvoice( entity );

	// ------------------------------------------
	// emit to subscribers that find all
	// ------------------------------------------    	
    emitFindAllInvoice( entity );
}



    /**
     * Method to retrieve the Invoice via an InvoicePrimaryKey.
     * @param 	id Long
     * @return 	Invoice
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Invoice handle( FindInvoiceQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getInvoiceId() );
    }
    
    /**
     * Method to retrieve a collection of all Invoices
     *
     * @param	query	FindAllInvoiceQuery 
     * @return 	List<Invoice> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Invoice> handle( FindAllInvoiceQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindInvoice,
 * but only if the id matches
 *
 * @param		entity	Invoice
 */
	protected void emitFindInvoice( Invoice entity ) {
		LOGGER.info("handling emitFindInvoice" );
		
	    queryUpdateEmitter.emit(FindInvoiceQuery.class,
	                            query -> query.getFilter().getInvoiceId().equals(entity.getInvoiceId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllInvoice
	 * 
	 * @param		entity	Invoice
	 */
	protected void emitFindAllInvoice( Invoice entity ) {
		LOGGER.info("handling emitFindAllInvoice" );
		
	    queryUpdateEmitter.emit(FindAllInvoiceQuery.class,
	                            query -> true,
	                            entity);
	}

	//--------------------------------------------------
    // attributes
